#include "DeleteArtworkResultObject.h"

#include "graphqlservice/internal/Schema.h"

#include "graphqlservice/introspection/IntrospectionSchema.h"

#include <algorithm>
#include <functional>
#include <sstream>
#include <stdexcept>
#include <unordered_map>

using namespace std::literals;

namespace graphql::tagimg {
namespace object {

DeleteArtworkResult::DeleteArtworkResult(std::unique_ptr<const Concept> pimpl) noexcept
	: service::Object{ getTypeNames(), getResolvers() }
	, _pimpl { std::move(pimpl) }
{
}

service::TypeNames DeleteArtworkResult::getTypeNames() const noexcept
{
	return {
		R"gql(DeleteArtworkResult)gql"sv
	};
}

service::ResolverMap DeleteArtworkResult::getResolvers() const noexcept
{
	return {
		{ R"gql(deleted)gql"sv, [this](service::ResolverParams&& params) { return resolveDeleted(std::move(params)); } },
		{ R"gql(__typename)gql"sv, [this](service::ResolverParams&& params) { return resolve_typename(std::move(params)); } },
		{ R"gql(newlyOrphanedImageCount)gql"sv, [this](service::ResolverParams&& params) { return resolveNewlyOrphanedImageCount(std::move(params)); } }
	};
}

void DeleteArtworkResult::beginSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->beginSelectionSet(params);
}

void DeleteArtworkResult::endSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->endSelectionSet(params);
}

service::AwaitableResolver DeleteArtworkResult::resolveDeleted(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getDeleted(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<bool>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver DeleteArtworkResult::resolveNewlyOrphanedImageCount(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getNewlyOrphanedImageCount(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<int>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver DeleteArtworkResult::resolve_typename(service::ResolverParams&& params) const
{
	return service::Result<std::string>::convert(std::string{ R"gql(DeleteArtworkResult)gql" }, std::move(params));
}

} // namespace object

void AddDeleteArtworkResultDetails(const std::shared_ptr<schema::ObjectType>& typeDeleteArtworkResult, const std::shared_ptr<schema::Schema>& schema)
{
	typeDeleteArtworkResult->AddFields({
		schema::Field::Make(R"gql(deleted)gql"sv, R"md(是否真的删除了作品；false 表示作品不存在。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(Boolean)gql"sv))),
		schema::Field::Make(R"gql(newlyOrphanedImageCount)gql"sv, R"md(本次删除释放出来的游离图片数量，不含删除前就已游离的图片。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(Int)gql"sv)))
	});
}

} // namespace graphql::tagimg
